      if (_AllowedResponse?.Any() == true) yield return new KeyValuePair<string,object>("allowedResponse",_AllowedResponse);
      if (_GraphElement is not null) yield return new KeyValuePair<string,object>("graph",_GraphElement);
    }

  }

